ALTER TABLE revisions ADD cycle integer NOT NULL DEFAULT 0;
ALTER TABLE approvals ADD cycle integer NOT NULL DEFAULT 0;
CREATE TABLE deviations (record_id uuid PRIMARY KEY REFERENCES records, description text NOT NULL, occurred_on date NOT NULL, reported_on date NOT NULL, risk text NOT NULL CHECK(risk IN ('Low','Medium','High')), impact text, containment text, investigation text, root_cause text, disposition text, capa_decision text CHECK(capa_decision IN ('Required','Not Required')), capa_reason text, status text NOT NULL DEFAULT 'Open' CHECK(status IN ('Open','Investigation','In Review','Closed','Cancelled')), owner_id uuid NOT NULL REFERENCES users, reviewed_by uuid REFERENCES users, version integer NOT NULL DEFAULT 1);
CREATE TABLE capas (record_id uuid PRIMARY KEY REFERENCES records, plan text NOT NULL, owner_id uuid NOT NULL REFERENCES users, due_at timestamptz NOT NULL, effectiveness_required boolean NOT NULL DEFAULT true, effectiveness_plan text, implementation_evidence_id uuid REFERENCES attachments, effectiveness_evidence_id uuid REFERENCES attachments, effectiveness_result text, status text NOT NULL DEFAULT 'Draft' CHECK(status IN ('Draft','Plan Approved','Implemented','Effectiveness Complete','Closed','Cancelled')), approved_by uuid REFERENCES users, closed_by uuid REFERENCES users, version integer NOT NULL DEFAULT 1);
CREATE TABLE quality_links (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), record_id uuid NOT NULL REFERENCES records, related_id uuid NOT NULL REFERENCES records, relation text NOT NULL, UNIQUE(record_id,related_id,relation), CHECK(record_id<>related_id));
CREATE TABLE changes (record_id uuid PRIMARY KEY REFERENCES records, description text NOT NULL, impact text NOT NULL, implementation_plan text NOT NULL, owner_id uuid NOT NULL REFERENCES users, status text NOT NULL DEFAULT 'Draft' CHECK(status IN ('Draft','Approved','Implemented','Closed','Cancelled')), evidence_id uuid REFERENCES attachments, approved_by uuid REFERENCES users, version integer NOT NULL DEFAULT 1);
CREATE TABLE audits (record_id uuid PRIMARY KEY REFERENCES records, audit_type text NOT NULL CHECK(audit_type IN ('Customer','Supplier','Internal')), scope text NOT NULL, target text NOT NULL, planned_on date NOT NULL, owner_id uuid NOT NULL REFERENCES users, status text NOT NULL DEFAULT 'Planned' CHECK(status IN ('Planned','In Progress','In Review','Closed','Cancelled')), report_id uuid REFERENCES attachments, version integer NOT NULL DEFAULT 1);
CREATE TABLE findings (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), record_id uuid NOT NULL REFERENCES audits, description text NOT NULL, grade text NOT NULL, owner_id uuid NOT NULL REFERENCES users, due_at timestamptz NOT NULL, response text, evidence_id uuid REFERENCES attachments, capa_id uuid REFERENCES capas(record_id), status text NOT NULL DEFAULT 'Open' CHECK(status IN ('Open','Closed')), closed_by uuid REFERENCES users, version integer NOT NULL DEFAULT 1);
CREATE TABLE approved_answers (record_id uuid PRIMARY KEY REFERENCES records, topic text NOT NULL, answer text NOT NULL, business_scope text NOT NULL, limitations text NOT NULL, source_revision_id uuid REFERENCES revisions, evidence_id uuid REFERENCES attachments, status text NOT NULL DEFAULT 'Draft' CHECK(status IN ('Draft','Approved','Needs Review','Cannot answer','Pending confirmation')), reviewed_by uuid REFERENCES users, reviewed_at timestamptz, valid_until date NOT NULL, version integer NOT NULL DEFAULT 1);
CREATE TABLE questionnaires (record_id uuid PRIMARY KEY REFERENCES records, owner_id uuid NOT NULL REFERENCES users, status text NOT NULL DEFAULT 'Draft' CHECK(status IN ('Draft','In Review','Submitted','Cancelled')), reviewed_by uuid REFERENCES users, version integer NOT NULL DEFAULT 1);
CREATE TABLE questions (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), record_id uuid NOT NULL REFERENCES questionnaires, question text NOT NULL, assignee_id uuid NOT NULL REFERENCES users, answer_id uuid REFERENCES approved_answers(record_id), draft_answer text NOT NULL DEFAULT 'Pending confirmation', evidence_id uuid REFERENCES attachments, promised_document text, version integer NOT NULL DEFAULT 1);
CREATE TABLE questionnaire_submissions (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), record_id uuid NOT NULL REFERENCES questionnaires, snapshot jsonb NOT NULL, submitted_by uuid NOT NULL REFERENCES users, created_at timestamptz NOT NULL DEFAULT now());
CREATE TRIGGER submission_immutable BEFORE UPDATE OR DELETE ON questionnaire_submissions FOR EACH ROW EXECUTE FUNCTION immutable_row();
CREATE TABLE locations (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), site_id uuid NOT NULL REFERENCES sites, parent_id uuid REFERENCES locations, name text NOT NULL, storage_condition text NOT NULL, UNIQUE(site_id,name));
CREATE TABLE materials (record_id uuid PRIMARY KEY REFERENCES records, material_type text NOT NULL CHECK(material_type IN ('Chemical','Cell','Antibody','Biological','Other')), ownership text NOT NULL CHECK(ownership IN ('BBC','Client','Third party')), supplier text NOT NULL, catalog text, storage_requirements text NOT NULL, cell_identity text, clone text, label text, usage_restrictions text);
CREATE TABLE material_uses (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), record_id uuid NOT NULL REFERENCES materials, project_id uuid NOT NULL REFERENCES projects, role text NOT NULL CHECK(role IN ('TA','Reference','Reagent','Other')), UNIQUE(record_id,project_id,role));
CREATE TABLE lots (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), record_id uuid NOT NULL REFERENCES materials, lot_number text NOT NULL, expires_on date NOT NULL, coa_id uuid REFERENCES attachments, sds_id uuid REFERENCES attachments, concentration text, status text NOT NULL DEFAULT 'On Hold' CHECK(status IN ('On Hold','Released','Disposed')), version integer NOT NULL DEFAULT 1, UNIQUE(record_id,lot_number));
CREATE TABLE containers (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), record_id uuid NOT NULL REFERENCES materials, lot_id uuid NOT NULL REFERENCES lots, parent_id uuid REFERENCES containers, label text NOT NULL, location_id uuid NOT NULL REFERENCES locations, unit text NOT NULL CHECK(unit IN ('mL','uL','mg','g','vial','each')), quantity numeric(20,6) NOT NULL CHECK(quantity>=0), reserved numeric(20,6) NOT NULL DEFAULT 0 CHECK(reserved>=0 AND reserved<=quantity), passage integer CHECK(passage>=0), freeze_thaw_count integer NOT NULL DEFAULT 0 CHECK(freeze_thaw_count>=0), opened_at timestamptz, status text NOT NULL DEFAULT 'Available' CHECK(status IN ('Available','Depleted','Disposed')), version integer NOT NULL DEFAULT 1);
CREATE TABLE inventory_transactions (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), record_id uuid NOT NULL REFERENCES materials, container_id uuid NOT NULL REFERENCES containers, operation text NOT NULL CHECK(operation IN ('Receive','Aliquot out','Aliquot in','Move','Reserve','Unreserve','Use','Adjust','Return','Dispose','Freeze thaw','Open')), delta numeric(20,6) NOT NULL, balance_after numeric(20,6) NOT NULL, unit text NOT NULL, project_id uuid REFERENCES projects, related_container_id uuid REFERENCES containers, location_id uuid REFERENCES locations, actor_id uuid NOT NULL REFERENCES users, reason text NOT NULL, created_at timestamptz NOT NULL DEFAULT now());
CREATE TRIGGER ledger_immutable BEFORE UPDATE OR DELETE ON inventory_transactions FOR EACH ROW EXECUTE FUNCTION immutable_row();
CREATE TABLE ehs_records (record_id uuid PRIMARY KEY REFERENCES records, category text NOT NULL CHECK(category IN ('Risk assessment','Material introduction','Permit','Inspection','Incident')), description text NOT NULL, assessment text, interim_measures text, corrective_action text, owner_id uuid NOT NULL REFERENCES users, due_at timestamptz NOT NULL, evidence_id uuid REFERENCES attachments, status text NOT NULL DEFAULT 'Open' CHECK(status IN ('Open','In Review','Closed','Cancelled')), closed_by uuid REFERENCES users, version integer NOT NULL DEFAULT 1);
DO $$ DECLARE t text; BEGIN
 FOREACH t IN ARRAY ARRAY['deviations','capas','quality_links','changes','audits','findings','approved_answers','questionnaires','questions','questionnaire_submissions','materials','material_uses','lots','containers','inventory_transactions','ehs_records'] LOOP
 EXECUTE format('ALTER TABLE %I ENABLE ROW LEVEL SECURITY',t);
 EXECUTE format('CREATE POLICY record_scope ON %I USING(can_record(record_id)) WITH CHECK(can_record(record_id))',t);
 EXECUTE format('CREATE TRIGGER business_audit AFTER INSERT OR UPDATE OR DELETE ON %I FOR EACH ROW EXECUTE FUNCTION audit_change()',t);
 END LOOP;
END $$;
-- A link never reveals the linked record when either endpoint is inaccessible.
DROP POLICY record_scope ON quality_links;
CREATE POLICY both_endpoints ON quality_links USING(can_record(record_id) AND can_record(related_id)) WITH CHECK(can_record(record_id) AND can_record(related_id));
ALTER TABLE locations ENABLE ROW LEVEL SECURITY;
CREATE POLICY location_scope ON locations USING(has_scope(actor_id(),site_id,NULL,NULL,NULL)) WITH CHECK(has_scope(actor_id(),site_id,NULL,NULL,NULL));
CREATE INDEX containers_lot ON containers(lot_id);
CREATE INDEX ledger_container ON inventory_transactions(container_id,created_at);
